SELECT ?point ?tsid WHERE {
  ?ahu a brick:AirHandlingUnit ; brick:hasIdentifier "AHU02" .
  ?point brick:isOutputOf ?ahu ; brick:hasType brick:ElectricPower .
  ?point ref:hasTimeseriesId ?tsid .
}

